async function request(action,payload,externalSignal){const ctl=new AbortController(),abort=()=>ctl.abort(),timer=setTimeout(abort,['booking','enquiry'].includes(action)?32000:26000);externalSignal?.addEventListener('abort',abort,{once:true});try{const r=await fetch('/api/leads.php',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({...payload,action,protocol:8}),signal:ctl.signal});let result;try{result=await r.json()}catch{const e=Error('The server response was not confirmed. Your draft and reference are kept.');e.delivery='unknown';throw e}if(action==='status'&&!result.ok&&(['BAD_ACTION'].includes(result.code)||/^(unknown|invalid) request\.?$|^invalid request\.?$/i.test(result.error||'')))return {status:'unsupported'};if(!r.ok||!result.ok){const e=Error(result.error||'The request could not be confirmed.');e.delivery=result.delivery;e.code=result.code;e.retryable=result.retryable||r.status>=500;throw e}if(['booking','enquiry'].includes(action)&&!result.status&&result.ok&&/^HADI-[a-f0-9-]{36}$/i.test(result.reference||'')&&typeof result.booking==='boolean')result={...result,status:result.booking?'booked':'received',meetingStatus:result.meetingStatus||'pending'};return result}finally{clearTimeout(timer);externalSignal?.removeEventListener('abort',abort)}}

async function checkPending(payload,attempts=3){for(let i=0;i<attempts;i++){try{const result=await request('status',{requestId:payload.requestId});if(['booked','received','unsupported'].includes(result.status))return result;if(result.status==='not_found'&&i===attempts-1)return result;}catch(e){if(e.code==='SLOT_UNAVAILABLE')throw e;if(i===attempts-1)return null}if(i<attempts-1)await new Promise(r=>setTimeout(r,4000));}return null}
function acceptResult(result){if(typeof result.reference!=='string'||!/^HADI-[a-f0-9-]{36}$/i.test(result.reference))throw Error('The reference was not confirmed.');if(!['booked','received'].includes(result.status)||(result.status==='booked'&&result.booking!==true))throw Error('The booking is still awaiting confirmation.');done=result;session={...session,pending:null};try{localStorage.removeItem(CHAT_KEY)}catch{}add('assistant',result.booking?(result.meetingStatus==='ready'?'Your call is reserved. The Google Meet link is ready below.':result.meetingStatus==='failed'?'Your call is reserved, but the meeting link needs Hadi’s attention. Use Connect to Hadi.':'Your call is reserved. Google is still preparing the meeting link; you can check it below.'):'Your brief has been received. Notification delivery is being processed.');}
async function refreshMeeting(){if(!done?.booking||busy)return;const id=done.reference.replace(/^HADI-/,'');busy=true;error='';render();try{const result=await request('status',{requestId:id});if(result.status==='booked')done=result;else error=result.status==='pending'?'The meeting link is still being prepared.':'The event could not be confirmed. Connect to Hadi with this reference.';}catch(e){error='The link could not be checked yet. Your reserved call has not been duplicated.'}finally{busy=false;render()}}
async function submit(action){if(busy)return;const wasPending=!!session.pending;try{let payload=session.pending;if(!payload){const id=crypto.randomUUID();payload=prepareLead(session,id,location.pathname);payload={...payload,action,...(action==='booking'?{slot:selectedSlot}:{})};session={...session,requestId:id,pending:payload};persist()}busy=true;error='';render();let result;
 if(wasPending){result=await checkPending(payload,1);if(result&&['booked','received'].includes(result.status)){acceptResult(result);return}if(!['not_found','unsupported'].includes(result?.status)){error='Confirmation is still pending. Your reference is saved. Check again; don’t create another booking.';return}}
 try{result=await request(payload.action,payload)}catch(e){if(e.delivery==='not_sent')throw e;result={status:'pending'}}
 if(result.status==='pending'||!result.status){add('assistant','I’m checking the same reference. Please keep it while Calendar confirms; no second booking is being created.');render();result=await checkPending(payload,3)}
 if(result&&['booked','received'].includes(result.status))acceptResult(result);else error='Confirmation is still pending. Your draft and reference are retained. Use Retry to check the same request.';
 }catch(e){error=e.name==='AbortError'?'The connection timed out. Your draft and reference are kept; retry safely.':e.message;if(e.code==='SLOT_UNAVAILABLE'||/that time was just booked/i.test(e.message)){slots=slots.filter(s=>s.start!==selectedSlot);selectedSlot='';session={...session,pending:null};bookingStage='calendar';voiceAwaitingConfirmation=false;availabilityCache.clear()}else if(e.delivery==='not_sent'&&['INVALID_CONTACT','INVALID_BRIEF','INVALID_SLOT','INVALID_SERVICE','INVALID_REFERENCE'].includes(e.code))session={...session,pending:null};}finally{busy=false;render()}}

