function voiceStop(){voiceGeneration++;voiceListening=false;voiceSpeaking=false;try{recognition?.abort()}catch{}recognition=null;try{window.speechSynthesis?.cancel()}catch{}if(panel){panel.dataset.state='idle';updateSera()}}
