function preferredFemaleVoice(){const voices=window.speechSynthesis?.getVoices?.()||[],language=($('.voice-language').value||'en-PK').slice(0,2);return voices.find(v=>v.voiceURI===preferredVoiceURI)||voices.find(v=>v.lang.startsWith(language)&&/samantha|karen|moira|tessa|zira|aria|jenny|natasha|susan|female|victoria|sara|serena|ava|allison|joanna/i.test(v.name))||voices.find(v=>v.lang.startsWith(language)&&/google us english|google uk english female/i.test(v.name))||voices.find(v=>v.lang.startsWith(language))||null}
