function startVoice(){voiceMode=true;voicePaused=false;voiceAutoSend=!$('.voice-review').checked;readAloud=true;render();if(booking){if(bookingStage==='details')promptBookingContact();else announceCalendar()}else if(review){announceBrief()}else{voiceStatus('Listening to you…');listen()}}
function bindVoice(){$('.voice-start').onclick=startVoice;$('.voice-mic').onclick=()=>{if(!voicePaused){voicePaused=true;voiceStop();voiceStatus('Conversation paused.')}else{voicePaused=false;listen()}};$('.voice-read').onclick=()=>{readAloud=!readAloud;$('.voice-read').setAttribute('aria-pressed',String(readAloud));$('.voice-read').setAttribute('aria-label',readAloud?'Mute Sera':'Hear Sera');if(!readAloud){voiceStop();resumeListening()}};$('.voice-end').onclick=()=>{voiceStop();voiceMode=false;voicePaused=true;render();input.focus()};$('.voice-language').onchange=()=>{voiceStop();voicePaused=false;listen()};$('.voice-review').onchange=e=>{voiceAutoSend=!e.target.checked;voiceStatus(voiceAutoSend?'Hands-free is on. Speak naturally.':'Review each transcript before sending.')};$('.voice-picker').onchange=e=>{preferredVoiceURI=e.target.value;try{localStorage.setItem('sera-voice-uri',preferredVoiceURI)}catch{}readReply('Hi, I’m Sera. Let’s talk about your project.')};populateVoicePicker();window.speechSynthesis?.addEventListener?.('voiceschanged',populateVoicePicker);}

